/* Collection checklists are stored on the parent; child library entries remain optional. */
(function(root){
 const key=m=>m.id;
 const eligible=m=>m?.format==='Collection'&&['movie','game'].includes(m.kind)&&m.source?.id?.startsWith('collection-');
 function update(previous,edition,rows,selected,done,more){const next=structuredClone(previous||{editions:{}});const old=next.editions[edition]||{completed:[]};const checked=new Set(old.completed);selected.forEach(id=>done?checked.add(id):checked.delete(id));const ids=more?[...new Set([...(old.ids||[]),...rows.map(key)])]:rows.map(key);next.editions[edition]={ids,completed:[...checked],total:more?(old.total||null):ids.length};next.active=edition;return next;}
 function progress(state,edition){const row=state?.editions?.[edition];return {completed:row?new Set(row.completed.filter(id=>row.ids.includes(id))).size:0,total:row?.total||null};}
 if(typeof module==='object')module.exports={key,update,progress,eligible};if(typeof document==='undefined')return;
 function bind(section,media,records,more){if(!eligible(media))return;const album=media,rows=records.filter(m=>m.kind===media.kind&&m.format!=='Collection'),unit=media.kind==='movie'?'Movies':'Games',noun=unit.toLowerCase();section.querySelector('.collection-progress-summary')?.remove();const edition=album.source.provider+':'+album.source.id;
  const entry=()=>items.find(x=>x.metadata&&FolioIdentity.same(x.metadata,media));
  const panel=document.createElement('div');panel.className='series-progress-summary collection-progress-summary';section.querySelector('.collection-groups').before(panel);
  const controls=[];rows.forEach(m=>{const i=records.indexOf(m),row=section.querySelector(`[data-part-view="${i}"]`)?.closest('.collection-row');if(!row)return;const label=document.createElement('label');label.className='collection-completion';label.innerHTML=`<input type="checkbox" aria-label="Completed ${media.kind==='movie'?'movie':'game'}: ${esc(m.title)}">`;row.prepend(label);const el=label.querySelector('input');el.onchange=e=>save([key(m)],e.target.checked);controls.push({el,m});});
  function draw(){const x=entry(),p=x?.collectionProgress?.editions?.[edition]?progress(x.collectionProgress,edition):{completed:0,total:more?null:rows.length},checked=new Set(x?.collectionProgress?.editions?.[edition]?.completed||[]);panel.innerHTML=x?`<strong>${p.completed}${p.total?' / '+p.total:''} ${noun} completed</strong><p>${more?'Load all entries to calculate the collection total.':'Checkmarks update collection progress automatically.'} Each title is tracked on this collection.</p>${p.total?`<progress value="${p.completed}" max="${p.total}" aria-label="Collection progress"></progress>`:''}<button type="button" data-complete-album ${more||!rows.length?'disabled':''}>${p.total&&p.completed===p.total?'Undo collection completion':'Mark collection complete'}</button>${x.collectionProgress?'<button type="button" data-manual-album>Use manual progress</button>':''}`:'Add the full collection to your library to save completion. Individual titles do not need to be added.';
   controls.forEach(({el,m})=>{el.checked=checked.has(key(m));el.disabled=!x;});panel.querySelector('[data-complete-album]')?.addEventListener('click',()=>save(rows.map(key),!(p.total&&p.completed===p.total)));panel.querySelector('[data-manual-album]')?.addEventListener('click',()=>{const old=x.collectionProgress;delete x.collectionProgress;if(!persist())x.collectionProgress=old;draw();});
   const dialog=section.closest('dialog');if(x&&dialog?.id==='detail'){for(const [selector,value] of [['#episodes-done',x.episodeProgress?.completed||0],['#episodes-total',x.episodeProgress?.total||''],['#progress-unit',unit]]){const el=dialog.querySelector(selector);if(el){if(x.collectionProgress){if(selector==='#progress-unit'&&![...el.options].some(o=>o.value===unit))el.add(new Option(unit,unit));el.value=value;}el.disabled=!!x.collectionProgress;}}const button=dialog.querySelector('#episode-form button[type=submit]');if(button)button.disabled=!!x.collectionProgress;const bar=dialog.querySelector('.activity-section progress');if(bar&&x.episodeProgress?.total){bar.max=x.episodeProgress.total;bar.value=x.episodeProgress.completed;}const text=dialog.querySelector('.activity-section progress + .muted');if(text&&x.collectionProgress)text.textContent=`${x.episodeProgress.completed} of ${x.episodeProgress.total||'unknown'} completed`;const note=dialog.querySelector('#episode-form .disclaimer');if(note)note.textContent=x.collectionProgress?'Title checkmarks control collection progress. Choose Use manual progress above to edit the count directly.':'Set overall progress manually, or use title checkmarks above.';}
  }
  function save(selected,done){try{const latest=JSON.parse(localStorage.getItem('folio-library-v1')||'null');if(Array.isArray(latest))items=root.FolioLibraryPatch?root.FolioLibraryPatch.entries(latest):latest;}catch{}const x=entry();if(!x)return;const before=structuredClone(x);if(!x.collectionProgress&&x.episodeProgress?.completed&&!confirm('Use title checkmarks instead of the manual count? Your previous count will be retained.')){draw();return;}if(!x.collectionProgress)x.previousManualCollectionProgress=structuredClone(x.episodeProgress||{});x.collectionProgress=update(x.collectionProgress,edition,rows,selected,done,more);x.episodeProgress=progress(x.collectionProgress,edition);x.progressUnit=unit;const p=x.episodeProgress;if(p.total&&p.completed===p.total)x.status='Completed';else if(p.completed||x.status==='Completed')x.status='In progress';delete x.completionPreviousStatus;if(!persist()){Object.keys(x).forEach(k=>delete x[k]);Object.assign(x,before);draw();return;}render();draw();section.closest('dialog').querySelectorAll('[data-status-id]').forEach(el=>{if(el.dataset.statusId===x.id)el.value=x.status;});toast(`${p.completed}${p.total?' / '+p.total:''} ${noun} completed`);}
  function onSave(){if(!section.isConnected||!panel.isConnected){document.removeEventListener('submit',onSave);return;}queueMicrotask(draw);}document.addEventListener('submit',onSave);draw();
 }
 root.FolioCollectionProgress={bind};
})(globalThis);
